CREATE TABLE automatic_records (guild_id text NOT NULL REFERENCES guilds(id) ON DELETE CASCADE, metric text NOT NULL, member_id uuid NOT NULL REFERENCES members(id) ON DELETE CASCADE, match_id uuid NOT NULL REFERENCES matches(id) ON DELETE CASCADE, value numeric NOT NULL, calculation_version integer NOT NULL DEFAULT 1, updated_at timestamptz NOT NULL DEFAULT now(), PRIMARY KEY(guild_id,metric));
CREATE TABLE personal_records (member_id uuid NOT NULL REFERENCES members(id) ON DELETE CASCADE, metric text NOT NULL, match_id uuid NOT NULL REFERENCES matches(id) ON DELETE CASCADE, value numeric NOT NULL, calculation_version integer NOT NULL DEFAULT 1, PRIMARY KEY(member_id,metric));
